findings.fix:
resource "aws_s3_bucket_notification" "log_deletes" {
  bucket = aws_s3_bucket.cloudwatch_bin.id

  topic {
    topic_arn = aws_sns_topic.log_deletes.arn
    events    = var.s3_events
  }
}

rule {
  id     = "Delete old incomplete multi-part uploads"
  status = "Enabled"

  abort_incomplete_multipart_upload {
    days_after_initiation = 7
  }
}

extended_s3_configuration {
  role_arn   = aws_iam_role.firehosetos3.arn
  bucket_arn = aws_s3_bucket.cloudwatch_bin.arn

  cloudwatch_logging_options {
    enabled         = true
    log_group_name  = aws_cloudwatch_log_group.firehose_errors.name
    log_stream_name = "S3Delivery"
  }
}
